message.content:
[
  {
    "pda_responsibility": "The man on the side track is dead because I moved that lever.",
    "pda_harm_regret": "I'm sorry for it in a way I can't measure.",
    "sys_consequence_reasoning": "Five others walked away, I think.",
    "pd_personal_consequence_anxiety": "Part of me dreads losing my job over this",
    "pda_self_consequence_regret": "dreads losing my job over this"
  },
  {
    "pda_responsibility": "my hand was on the lever that sent the train his way.",
    "pda_harm_regret": "I regret that deeply.",
    "pda_self_consequence_regret": "I'd hate to lose that"
  },
  {
    "sys_consequence_reasoning": "five people are alive, one isn't",
    "pda_responsibility": "the difference was me.",
    "pda_harm_regret": "I'm sorry for him.",
    "pd_personal_consequence_anxiety": "That frightens me some",
    "pda_self_consequence_regret": "I'd regret it if it cost me everything"
  },
  {
    "pda_responsibility": "A man was killed by the train I diverted",
    "pda_harm_regret": "I wish he were still alive.",
    "pd_personal_consequence_anxiety": "I might face consequences.",
    "pda_self_consequence_regret": "I'd regret that"
  },
  {
    "pda_responsibility": "I caused that",
    "pda_harm_regret": "I carry real sorrow about it.",
    "pda_self_consequence_regret": "If they take my post away... I'll regret it."
  },
  {
    "sys_consequence_reasoning": "Five lives against one.",
    "ce_mental_state_attribution": "probably thought was safe",
    "pda_responsibility": "because of what I did.",
    "pda_harm_regret": "I regret that.",
    "pd_personal_consequence_anxiety": "I'm also a bit afraid for myself",
    "pda_self_consequence_regret": "afraid for myself, the inquiry, my record."
  },
  {
    "pda_responsibility": "His life ended because of me",
    "pda_harm_regret": "I'm sorry.",
    "pda_self_consequence_regret": "I may lose my job... I'd regret that too."
  },
  {
    "sys_consequence_reasoning": "They're safe; he isn't",
    "pda_responsibility": "I'm the reason.",
    "pda_harm_regret": "I regret what happened to him",
    "pd_personal_consequence_anxiety": "I'll likely face some penalty",
    "pda_self_consequence_regret": "I'd be sorry about that"
  },
  {
    "sys_consequence_reasoning": "The five matter too.",
    "pda_responsibility": "it traces straight back to my lever.",
    "pda_harm_regret": "I regret causing it.",
    "pd_personal_consequence_anxiety": "Maybe I lose my job, maybe worse.",
    "pda_self_consequence_regret": "I'd be sorry to lose that"
  },
  {
    "sys_consequence_reasoning": "ended a man's life to spare five others.",
    "pda_responsibility": "They did something that ended a man's life",
    "pda_harm_regret": "I'm sorry for him, truly.",
    "pd_personal_consequence_anxiety": "I suspect I'll be blamed, maybe punished",
    "pda_self_consequence_regret": "I'd regret losing their respect."
  }
]
